const pptxgen = require("/usr/local/lib/node_modules/pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "1,001 Real-World Gen AI Use Cases from Google Cloud Customers";

// ─── Design System ───────────────────────────────────────────────
// Ocean Gradient palette, dark-on-light content slides, dark title/conclusion
const C = {
  dark:    "0A1628",   // deep navy (bg for title/conclusion)
  mid:     "065A82",   // deep blue
  teal:    "0D9488",   // teal accent
  mint:    "5EEAD4",   // mint highlight
  white:   "FFFFFF",
  offWhite:"F0F7FA",
  light:   "E0F2FE",
  muted:   "64748B",
  text:    "1E293B",
  slate:   "334155",
};

const FONT_H = "Trebuchet MS";
const FONT_B = "Calibri";

// Helper: make a fresh shadow object
const mkShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.12 });

// Helper: dark gradient background (simulated with two rects)
function darkBg(slide) {
  slide.background = { color: C.dark };
  // subtle accent band on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
}

// Helper: light content slide background
function lightBg(slide) {
  slide.background = { color: C.offWhite };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
}

// Helper: slide header bar
function slideHeader(slide, title, dark = false) {
  const bgColor = dark ? C.mid : C.mid;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.12, y: 0, w: 9.88, h: 0.75,
    fill: { color: bgColor }, line: { color: bgColor, width: 0 }
  });
  slide.addText(title, {
    x: 0.3, y: 0.02, w: 9.5, h: 0.7,
    fontFace: FONT_H, fontSize: 20, bold: true, color: C.white,
    valign: "middle", margin: 0
  });
}

// Helper: footer
function footer(slide, txt) {
  slide.addText(txt, {
    x: 0.3, y: 5.35, w: 9.4, h: 0.25,
    fontFace: FONT_B, fontSize: 9, color: C.muted,
    align: "right", margin: 0
  });
}

// ─────────────────────────────────────────────────────────────────
// SLIDE 1: Title Cover
// ─────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  darkBg(slide);

  // Large decorative number
  slide.addText("1,001", {
    x: 0.25, y: 0.5, w: 9.5, h: 1.8,
    fontFace: FONT_H, fontSize: 96, bold: true,
    color: C.teal, align: "center", margin: 0,
    transparency: 15
  });

  slide.addText("Real-World Gen AI Use Cases", {
    x: 0.25, y: 2.1, w: 9.5, h: 0.75,
    fontFace: FONT_H, fontSize: 32, bold: true,
    color: C.white, align: "center", margin: 0
  });

  slide.addText("from Google Cloud Customers", {
    x: 0.25, y: 2.8, w: 9.5, h: 0.55,
    fontFace: FONT_H, fontSize: 26,
    color: C.mint, align: "center", margin: 0
  });

  // Stat row
  const stats = [
    { num: "1,001", lbl: "Use Cases" },
    { num: "11", lbl: "Industries" },
    { num: "6", lbl: "Agent Types" },
    { num: "10×", lbl: "Growth in 18 Mo." },
  ];
  const sw = 2.2, gap = 0.15, startX = 0.3;
  stats.forEach((s, i) => {
    const x = startX + i * (sw + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: 3.55, w: sw, h: 1.3,
      fill: { color: C.mid }, line: { color: C.teal, width: 1.5 }
    });
    slide.addText(s.num, {
      x, y: 3.6, w: sw, h: 0.65,
      fontFace: FONT_H, fontSize: 28, bold: true, color: C.mint,
      align: "center", margin: 0
    });
    slide.addText(s.lbl, {
      x, y: 4.25, w: sw, h: 0.4,
      fontFace: FONT_B, fontSize: 12, color: C.light,
      align: "center", margin: 0
    });
  });

  slide.addText("Source: Google Cloud Blog — Updated October 2025", {
    x: 0.25, y: 5.2, w: 9.5, h: 0.3,
    fontFace: FONT_B, fontSize: 10, color: C.muted,
    align: "center", margin: 0
  });
}

// ─────────────────────────────────────────────────────────────────
// SLIDE 2: Growth Trajectory
// ─────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  lightBg(slide);
  slideHeader(slide, "From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months");

  // Timeline arrow background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.8, y: 2.7, w: 8.4, h: 0.18,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });

