const FONT_H = "Trebuchet MS";
const FONT_B = "Calibri";

// Helper: make a fresh shadow object
const mkShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.12 });

// Helper: dark gradient background (simulated with two rects)
function darkBg(slide) {
  slide.background = { color: C.dark };
  // subtle accent band on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
}

// Helper: light content slide background
function lightBg(slide) {
  slide.background = { color: C.offWhite };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
}

// Helper: slide header bar
function slideHeader(slide, title, dark = false) {
  const bgColor = dark ? C.mid : C.mid;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.12, y: 0, w: 9.88, h: 0.75,
