    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.18, y, w: 0.2, h: 1.38,
      fill: { color: p.color }, line: { color: p.color, width: 0 }
    });

    // Number badge
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: y + 0.05, w: 0.55, h: 0.55,
      fill: { color: p.color }, line: { color: p.color, width: 0 }
    });
    slide.addText(p.num, {
      x: 0.5, y: y + 0.05, w: 0.55, h: 0.55,
      fontFace: FONT_H, fontSize: 14, bold: true, color: C.white,
      align: "center", valign: "middle", margin: 0
    });

    // Title
    slide.addText(p.title, {
      x: 1.2, y: y + 0.1, w: 8.4, h: 0.38,
      fontFace: FONT_H, fontSize: 16, bold: true, color: C.text,
      margin: 0
    });

    // Description
    slide.addText(p.desc, {
      x: 1.2, y: y + 0.45, w: 8.4, h: 0.45,
      fontFace: FONT_B, fontSize: 11, color: C.slate,
      margin: 0
    });

    // Examples
    slide.addText("Companies: " + p.examples, {
      x: 1.2, y: y + 0.92, w: 8.4, h: 0.3,
      fontFace: FONT_B, fontSize: 10, italic: true, color: C.muted,
      margin: 0
    });
  });

  footer(slide, "Google Cloud Blog — Cross-industry analysis, October 2025");
}

// ─────────────────────────────────────────────────────────────────
// SLIDE 7: Strategic Takeaways
// ─────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  darkBg(slide);

  // Header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.12, y: 0, w: 9.88, h: 0.75,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  slide.addText("Takeaways: Where to Start and What to Expect from Enterprise Gen AI", {
    x: 0.3, y: 0.02, w: 9.5, h: 0.7,
    fontFace: FONT_H, fontSize: 18, bold: true, color: C.dark,
    valign: "middle", margin: 0
  });

  const takeaways = [
    {
      num: "1",
      head: "Gen AI is production-ready across all major industries",
      body: "All 11 verticals have live deployments. This is no longer experimental — the question is not if, but where to deploy first.",
    },
    {
      num: "2",
      head: "Customer & Employee agents are the highest-probability entry points",
      body: "Conversational assistants and Gemini for Workspace represent the most common and fastest-to-value deployment patterns.",
    },
    {
      num: "3",
      head: "Measurable ROI is achievable within months",
      body: "500% ROI (Mercari), 30% workload reduction (LUXGEN), 10,000+ hours saved (Toyota) — organizations are reporting hard numbers from production.",
    },
    {
      num: "4",
      head: "Creative and Code agents are the fastest-growing frontier",
      body: "Multimodal creation (Virgin Voyages, PODS) and AI-assisted coding (Renault Ampere) signal the next wave of enterprise adoption.",
    },
    {
      num: "5",
      head: "Early movers gain compounding advantages",
      body: "With 400 new use cases added in a single update cycle, the deployment gap between leaders and laggards widens every quarter.",
    },
  ];

  takeaways.forEach((t, i) => {
    const y = 0.88 + i * 0.9;

    slide.addShape(pres.shapes.OVAL, {
      x: 0.2, y: y + 0.04, w: 0.44, h: 0.44,
      fill: { color: C.teal }, line: { color: C.teal, width: 0 }
    });
    slide.addText(t.num, {
      x: 0.2, y: y + 0.04, w: 0.44, h: 0.44,
      fontFace: FONT_H, fontSize: 14, bold: true, color: C.dark,
      align: "center", valign: "middle", margin: 0
    });

    slide.addText(t.head, {
      x: 0.78, y: y + 0.05, w: 8.9, h: 0.35,
      fontFace: FONT_H, fontSize: 13, bold: true, color: C.mint,
      margin: 0
    });
    slide.addText(t.body, {
      x: 0.78, y: y + 0.4, w: 8.9, h: 0.38,
      fontFace: FONT_B, fontSize: 11, color: C.light,
      margin: 0
    });
  });

  slide.addText("Source: Google Cloud Blog — 1,001 real-world gen AI use cases, October 2025", {
    x: 0.25, y: 5.32, w: 9.5, h: 0.22,
    fontFace: FONT_B, fontSize: 9, color: C.muted,
    align: "center", margin: 0
  });
}

// ─────────────────────────────────────────────────────────────────
// Write output
// ─────────────────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Saved: /app/output/final_deck.pptx"))
  .catch(err => { console.error(err); process.exit(1); });

