      fontFace: FONT_B, fontSize: 12, color: C.light,
      align: "center", margin: 0
    });
  });

  slide.addText("Source: Google Cloud Blog — Updated October 2025", {
    x: 0.25, y: 5.2, w: 9.5, h: 0.3,
    fontFace: FONT_B, fontSize: 10, color: C.muted,
    align: "center", margin: 0
  });
}

